        if first_tr and first_tr.find_all('th'):
            data_trs = trs[1:]
    else:
        # no headers, all trs are data rows
        data_trs = trs

    for tr in data_trs:
        tds = tr.find_all('td')
        if not tds:
            continue
        row = [td.get_text(strip=True) for td in tds]
        rows.append(row)

    if not rows:
